@page "/settings"
@using sv_ab5c6ecb0ec849ed99b4ac391fc83b0b.Services
@inject ISettingsService SettingsService
@rendermode InteractiveServer

<PageTitle>Settings</PageTitle>

<div class="settings-container">
    <nav class="settings-sidebar">
        <h2 class="settings-title">Settings</h2>
        <ul class="settings-nav">
            @foreach (var section in _sections)
            {
                <li class="@(ActiveSection == section.Key ? "active" : "")" @onclick="() => ActiveSection = section.Key">
                    <span class="nav-icon">@section.Value.Icon</span>
                    <span>@section.Value.Label</span>
                </li>
            }
        </ul>
    </nav>

    <main class="settings-content">
        @if (_loading)
        {
            <div class="loading-spinner">Loading...</div>
        }
        else
        {
            @if (!string.IsNullOrEmpty(_toastMessage))
            {
                <div class="toast @_toastType">@_toastMessage</div>
            }

            @switch (ActiveSection)
            {
                case "profile":
                    @RenderProfileSection()
                    break;
                case "notifications":
                    @RenderNotificationsSection()
                    break;
                case "security":
                    @RenderSecuritySection()
                    break;
                case "appearance":
                    @RenderAppearanceSection()
                    break;
            }
        }
    </main>
</div>

@* --- Profile Section --- *@
@{
    RenderFragment RenderProfileSection() => __builder2 =>
    {
        <section class="settings-section">
            <h3>Profile</h3>
            <div class="avatar-preview">
                <img src="@_profileDisplayName" alt="Avatar" onerror="this.style.display='none'" />
                @* Show avatar URL below *@
                <p class="avatar-url">@_profileAvatarUrl</p>
            </div>
            <div class="form-group">
                <label for="displayName">Display Name</label>
                <input id="displayName" type="text" @bind="_profileDisplayName" @bind:event="oninput" />
            </div>
            <div class="form-group">
                <label for="email">Email</label>
                <input id="email" type="email" @bind="_profileEmail" @bind:event="oninput" />
            </div>
            <div class="form-group">
                <label for="bio">Bio</label>
                <textarea id="bio" rows="4" @bind="_profileBio" @bind:event="oninput"></textarea>
            </div>
            <div class="form-group">
                <label for="avatarUrl">Avatar URL</label>
                <input id="avatarUrl" type="url" @bind="_profileAvatarUrl" @bind:event="oninput" />
            </div>
            <div class="button-group">
                <button class="btn btn-primary" @onclick="SaveProfile">Save Changes</button>
                <button class="btn btn-secondary" @onclick="DiscardProfileChanges">Discard Changes</button>
            </div>
        </section>
    };
}

@* --- Notifications Section --- *@
@{
    RenderFragment RenderNotificationsSection() => __builder2 =>
    {
        <section class="settings-section">
            <h3>Notifications</h3>
            <div class="toggle-group">
                <label class="toggle-item">
                    <span>Email Notifications</span>
                    <input type="checkbox" @bind="_emailNotifications" />
                    <span class="toggle-switch"></span>
                </label>
                <label class="toggle-item">
                    <span>Push Notifications</span>
                    <input type="checkbox" @bind="_pushNotifications" />
                    <span class="toggle-switch"></span>
                </label>
                <label class="toggle-item">
                    <span>Weekly Digest</span>
                    <input type="checkbox" @bind="_weeklyDigest" />
                    <span class="toggle-switch"></span>
                </label>
            </div>

            <h4>Muted Channels</h4>
            <div class="channel-list">
                @foreach (var channel in _allChannels)
                {
                    var isMuted = _mutedChannels.Contains(channel);
                    <label class="channel-item">
                        <input type="checkbox" checked="@isMuted" @onchange="e => ToggleMuteChannel(channel, (bool)e.Value!)" />
                        <span>@channel</span>
                    </label>
                }
            </div>

            <div class="button-group">
                <button class="btn btn-primary" @onclick="SaveNotifications">Save Preferences</button>
            </div>
        </section>
    };
}

@* --- Security Section --- *@
@{
    RenderFragment RenderSecuritySection() => __builder2 =>
    {
        <section class="settings-section">
            <h3>Security</h3>

            <div class="expandable-panel">
                <button class="panel-header" @onclick="() => _passwordPanelExpanded = !_passwordPanelExpanded">
                    <span>Change Password</span>
                    <span class="expand-icon">@(_passwordPanelExpanded ? "▾" : "▸")</span>
                </button>
                @if (_passwordPanelExpanded)
                {
                    <div class="panel-body">
                        <div class="form-group">
                            <label for="currentPassword">Current Password</label>
                            <input id="currentPassword" type="password" @bind="_currentPassword" />
                        </div>
                        <div class="form-group">
                            <label for="newPassword">New Password</label>
                            <input id="newPassword" type="password" @bind="_newPassword" />
                        </div>
                        <div class="form-group">
                            <label for="confirmPassword">Confirm Password</label>
                            <input id="confirmPassword" type="password" @bind="_confirmPassword" />
                        </div>
                        <button class="btn btn-primary" @onclick="UpdatePassword">Update Password</button>
                    </div>
                }
            </div>

            <div class="toggle-group" style="margin-top: 1.5rem;">
                <label class="toggle-item">
                    <span>Two-Factor Authentication</span>
                    <input type="checkbox" @bind="_twoFactorEnabled" />
                    <span class="toggle-switch"></span>
                    <span class="status-indicator @(_twoFactorEnabled ? "enabled" : "disabled")">
                        @(_twoFactorEnabled ? "Enabled" : "Disabled")
                    </span>
                </label>
            </div>

            @if (_securitySettings?.LastPasswordChange != null)
            {
                <p class="info-text">Last password change: @_securitySettings.LastPasswordChange.Value.ToString("MMMM dd, yyyy")</p>
            }

            <h4>Active Sessions</h4>
            <table class="sessions-table">
                <thead>
                    <tr>
                        <th>Device</th>
                        <th>Location</th>
                        <th>Last Active</th>
                        <th></th>
                    </tr>
                </thead>
                <tbody>
                    @if (_securitySettings?.Sessions != null)
                    {
                        @foreach (var session in _securitySettings.Sessions)
                        {
                            <tr>
                                <td>@session.Device</td>
                                <td>@session.Location</td>
                                <td>@FormatLastActive(session.LastActive)</td>
                                <td>
                                    @if (session.Id != _currentSessionId)
                                    {
                                        <button class="btn btn-danger btn-sm" @onclick="() => ConfirmRevokeSession(session)">Revoke</button>
                                    }
                                    else
                                    {
                                        <span class="current-badge">Current</span>
                                    }
                                </td>
                            </tr>
                        }
                    }
                </tbody>
            </table>

            @if (_sessionToRevoke != null)
            {
                <div class="modal-overlay" @onclick="CancelRevoke">
                    <div class="modal" @onclick:stopPropagation="true">
                        <h4>Confirm Session Revocation</h4>
                        <p>Are you sure you want to revoke the session on <strong>@_sessionToRevoke.Device</strong> from <strong>@_sessionToRevoke.Location</strong>?</p>
                        <div class="button-group">
                            <button class="btn btn-danger" @onclick="RevokeSession">Revoke Session</button>
                            <button class="btn btn-secondary" @onclick="CancelRevoke">Cancel</button>
                        </div>
                    </div>
                </div>
            }
        </section>
    };
}

@* --- Appearance Section --- *@
@{
    RenderFragment RenderAppearanceSection() => __builder2 =>
    {
        <section class="settings-section">
            <h3>Appearance</h3>

            <div class="form-group">
                <label>Theme</label>
                <div class="radio-group">
                    @foreach (var theme in new[] { "Light", "Dark", "System" })
                    {
                        <label class="radio-item">
                            <input type="radio" name="theme" value="@theme" checked="@(_appearanceTheme == theme)" @onchange="() => _appearanceTheme = theme" />
                            <span>@theme</span>
                        </label>
                    }
                </div>
            </div>

            <div class="form-group">
                <label>Font Size</label>
                <div class="radio-group">
                    @foreach (var size in new[] { "Small", "Medium", "Large" })
                    {
                        <label class="radio-item">
                            <input type="radio" name="fontSize" value="@size" checked="@(_appearanceFontSize == size)" @onchange="() => _appearanceFontSize = size" />
                            <span>@size</span>
                        </label>
                    }
                </div>
            </div>

            <div class="form-group">
                <label for="language">Language</label>
                <select id="language" @bind="_appearanceLanguage">
                    <option value="English">English</option>
                    <option value="Spanish">Spanish</option>
                    <option value="French">French</option>
                    <option value="German">German</option>
                    <option value="Japanese">Japanese</option>
                    <option value="Chinese">Chinese</option>
                </select>
            </div>

            <div class="toggle-group">
                <label class="toggle-item">
                    <span>Compact Mode</span>
                    <input type="checkbox" @bind="_appearanceCompactMode" />
                    <span class="toggle-switch"></span>
                </label>
            </div>

            <h4>Preview</h4>
            <div class="appearance-preview @GetPreviewClasses()">
                <div class="preview-header">Sample Header</div>
                <p class="preview-text">This is how your content will look with the selected appearance settings.</p>
                <button class="preview-button">Sample Button</button>
            </div>

            <div class="button-group">
                <button class="btn btn-primary" @onclick="SaveAppearance">Save</button>
            </div>
        </section>
    };
}

@code {
    private string ActiveSection { get; set; } = "profile";
    private bool _loading = true;
    private string? _toastMessage;
    private string _toastType = "success";

    // Section metadata
    private readonly Dictionary<string, (string Label, string Icon)> _sections = new()
    {
        ["profile"] = ("Profile", "👤"),
        ["notifications"] = ("Notifications", "🔔"),
        ["security"] = ("Security", "🔒"),
        ["appearance"] = ("Appearance", "🎨")
    };

    // Profile state
    private string _profileDisplayName = "";
    private string _profileEmail = "";
    private string _profileAvatarUrl = "";
    private string _profileBio = "";
    private UserProfile? _savedProfile;

    // Notifications state
    private bool _emailNotifications;
    private bool _pushNotifications;
    private bool _weeklyDigest;
    private List<string> _mutedChannels = new();
    private readonly List<string> _allChannels = new() { "general", "marketing", "engineering", "design", "announcements" };

    // Security state
    private SecuritySettings? _securitySettings;
    private bool _passwordPanelExpanded;
    private string _currentPassword = "";
    private string _newPassword = "";
    private string _confirmPassword = "";
    private bool _twoFactorEnabled;
    private ActiveSession? _sessionToRevoke;
    private readonly string _currentSessionId = "sess-1";

    // Appearance state
    private string _appearanceTheme = "System";
    private string _appearanceFontSize = "Medium";
    private string _appearanceLanguage = "English";
    private bool _appearanceCompactMode;

    protected override async Task OnInitializedAsync()
    {
        await LoadAllSettings();
        _loading = false;
    }

    private async Task LoadAllSettings()
    {
        var profile = await SettingsService.GetProfileAsync();
        _savedProfile = profile;
        SetProfileFields(profile);

        var notifs = await SettingsService.GetNotificationPrefsAsync();
        _emailNotifications = notifs.EmailNotifications;
        _pushNotifications = notifs.PushNotifications;
        _weeklyDigest = notifs.WeeklyDigest;
        _mutedChannels = new List<string>(notifs.MutedChannels);

        _securitySettings = await SettingsService.GetSecuritySettingsAsync();
        _twoFactorEnabled = _securitySettings.TwoFactorEnabled;

        var appearance = await SettingsService.GetAppearanceAsync();
        _appearanceTheme = appearance.Theme;
        _appearanceFontSize = appearance.FontSize;
        _appearanceLanguage = appearance.Language;
        _appearanceCompactMode = appearance.CompactMode;
    }

    private void SetProfileFields(UserProfile profile)
    {
        _profileDisplayName = profile.DisplayName;
        _profileEmail = profile.Email;
        _profileAvatarUrl = profile.AvatarUrl;
        _profileBio = profile.Bio;
    }

    // Profile actions
    private async Task SaveProfile()
    {
        var profile = new UserProfile(_profileDisplayName, _profileEmail, _profileAvatarUrl, _profileBio);
        await SettingsService.SaveProfileAsync(profile);
        _savedProfile = profile;
        ShowToast("Profile saved successfully!", "success");
    }

    private void DiscardProfileChanges()
    {
        if (_savedProfile != null)
        {
            SetProfileFields(_savedProfile);
        }
        ShowToast("Changes discarded.", "info");
    }

    // Notifications actions
    private void ToggleMuteChannel(string channel, bool muted)
    {
        if (muted && !_mutedChannels.Contains(channel))
            _mutedChannels.Add(channel);
        else if (!muted)
            _mutedChannels.Remove(channel);
    }

    private async Task SaveNotifications()
    {
        var prefs = new NotificationPrefs(_emailNotifications, _pushNotifications, _weeklyDigest, new List<string>(_mutedChannels));
        await SettingsService.SaveNotificationPrefsAsync(prefs);
        ShowToast("Notification preferences saved!", "success");
    }

    // Security actions
    private async Task UpdatePassword()
    {
        if (string.IsNullOrWhiteSpace(_currentPassword) || string.IsNullOrWhiteSpace(_newPassword))
        {
            ShowToast("Please fill in all password fields.", "error");
            return;
        }
        if (_newPassword != _confirmPassword)
        {
            ShowToast("New password and confirmation do not match.", "error");
            return;
        }
        await SettingsService.ChangePasswordAsync(_currentPassword, _newPassword);
        _currentPassword = "";
        _newPassword = "";
        _confirmPassword = "";
        _securitySettings = await SettingsService.GetSecuritySettingsAsync();
        ShowToast("Password updated successfully!", "success");
    }

    private void ConfirmRevokeSession(ActiveSession session)
    {
        _sessionToRevoke = session;
    }

    private void CancelRevoke()
    {
        _sessionToRevoke = null;
    }

    private async Task RevokeSession()
    {
        if (_sessionToRevoke != null)
        {
            await SettingsService.RevokeSessionAsync(_sessionToRevoke.Id);
            _securitySettings = await SettingsService.GetSecuritySettingsAsync();
            _sessionToRevoke = null;
            ShowToast("Session revoked.", "success");
        }
    }

    // Appearance actions
    private string GetPreviewClasses()
    {
        var classes = new List<string>();
        classes.Add($"preview-theme-{_appearanceTheme.ToLowerInvariant()}");
        classes.Add($"preview-font-{_appearanceFontSize.ToLowerInvariant()}");
        if (_appearanceCompactMode) classes.Add("preview-compact");
        return string.Join(" ", classes);
    }

    private async Task SaveAppearance()
    {
        var settings = new AppearanceSettings(_appearanceTheme, _appearanceFontSize, _appearanceLanguage, _appearanceCompactMode);
        await SettingsService.SaveAppearanceAsync(settings);
        ShowToast("Appearance settings saved!", "success");
    }

    // Toast helpers
    private void ShowToast(string message, string type)
    {
        _toastMessage = message;
        _toastType = type;
        _ = DismissToastAfterDelay();
    }

    private async Task DismissToastAfterDelay()
    {
        await Task.Delay(3000);
        _toastMessage = null;
        await InvokeAsync(StateHasChanged);
    }

    private static string FormatLastActive(DateTime lastActive)
    {
        var diff = DateTime.UtcNow - lastActive;
        if (diff.TotalMinutes < 60) return $"{(int)diff.TotalMinutes} min ago";
        if (diff.TotalHours < 24) return $"{(int)diff.TotalHours} hours ago";
        return $"{(int)diff.TotalDays} days ago";
    }
}

.settings-container {
    display: flex;
    min-height: calc(100vh - 4rem);
    max-width: 1200px;
    margin: 0 auto;
    gap: 2rem;
    padding: 2rem;
}

/* Sidebar */
.settings-sidebar {
    width: 220px;
    flex-shrink: 0;
}

.settings-title {
    font-size: 1.25rem;
    font-weight: 700;
    margin-bottom: 1rem;
    padding: 0.5rem 1rem;
}

.settings-nav {
    list-style: none;
    padding: 0;
    margin: 0;
}

.settings-nav li {
    display: flex;
    align-items: center;
    gap: 0.75rem;
    padding: 0.75rem 1rem;
    border-radius: 8px;
    cursor: pointer;
    transition: background 0.2s, color 0.2s;
    font-weight: 500;
    color: #555;
}

.settings-nav li:hover {
    background: #f0f0f0;
    color: #111;
}

.settings-nav li.active {
    background: #e8f0fe;
    color: #1a73e8;
    font-weight: 600;
}

.nav-icon {
    font-size: 1.1rem;
}

/* Content */
.settings-content {
    flex: 1;
    min-width: 0;
}

.settings-section h3 {
    font-size: 1.5rem;
    font-weight: 700;
    margin-bottom: 1.5rem;
    padding-bottom: 0.75rem;
    border-bottom: 1px solid #e0e0e0;
}

.settings-section h4 {
    font-size: 1.1rem;
    font-weight: 600;
    margin-top: 1.5rem;
    margin-bottom: 0.75rem;
}

/* Forms */
.form-group {
    margin-bottom: 1.25rem;
}

.form-group label {
    display: block;
    font-weight: 500;
    margin-bottom: 0.4rem;
    color: #333;
}

.form-group input[type="text"],
.form-group input[type="email"],
.form-group input[type="url"],
.form-group input[type="password"],
.form-group textarea,
.form-group select {
    width: 100%;
    max-width: 450px;
    padding: 0.6rem 0.75rem;
    border: 1px solid #ccc;
