                <label for="bio">Bio</label>
                <textarea id="bio" rows="4" @bind="_profileBio" @bind:event="oninput"></textarea>
            </div>
            <div class="form-group">
                <label for="avatarUrl">Avatar URL</label>
                <input id="avatarUrl" type="url" @bind="_profileAvatarUrl" @bind:event="oninput" />
            </div>
