    box-shadow: 0 8px 32px rgba(0, 0, 0, 0.2);
}

.modal h4 {
    margin-top: 0;
    margin-bottom: 0.75rem;
}

.modal p {
    margin-bottom: 1.5rem;
    color: #555;
}

/* Radio group */
.radio-group {
    display: flex;
    gap: 1.25rem;
    margin-top: 0.3rem;
}

.radio-item {
