    align-items: center;
    gap: 0.4rem;
    cursor: pointer;
}

.radio-item input[type="radio"] {
    accent-color: #1a73e8;
}

/* Appearance preview */
.appearance-preview {
    border: 1px solid #e0e0e0;
    border-radius: 8px;
    padding: 1.5rem;
    margin-top: 0.75rem;
    margin-bottom: 1rem;
    transition: all 0.3s;
}

.appearance-preview.preview-theme-light {
    background: #ffffff;
    color: #333;
}

.appearance-preview.preview-theme-dark {
    background: #1e1e2e;
    color: #e0e0e0;
    border-color: #444;
}

.appearance-preview.preview-theme-system {
    background: #f8f9fa;
    color: #333;
}

.appearance-preview.preview-font-small {
    font-size: 0.8rem;
}

.appearance-preview.preview-font-medium {
    font-size: 1rem;
}

.appearance-preview.preview-font-large {
    font-size: 1.2rem;
}

.appearance-preview.preview-compact {
    padding: 0.75rem;
    line-height: 1.3;
}

.preview-header {
    font-weight: 700;
    font-size: 1.1em;
    margin-bottom: 0.5rem;
}

.preview-text {
    margin-bottom: 0.75rem;
    opacity: 0.85;
}

.preview-button {
    padding: 0.4rem 1rem;
    border-radius: 4px;
    border: 1px solid currentColor;
    background: transparent;
    color: inherit;
    cursor: pointer;
    font-size: 0.9em;
}

/* Toast */
.toast {
    padding: 0.75rem 1rem;
    border-radius: 6px;
    margin-bottom: 1.25rem;
    font-size: 0.9rem;
    font-weight: 500;
    animation: slideIn 0.3s ease;
}

.toast.success {
    background: #e6f4ea;
    color: #137333;
    border: 1px solid #a8dab5;
}

.toast.error {
    background: #fce8e6;
    color: #c5221f;
    border: 1px solid #f5c6cb;
}

.toast.info {
    background: #e8f0fe;
    color: #1a73e8;
    border: 1px solid #b6d4fe;
}

@keyframes slideIn {
    from {
        opacity: 0;
        transform: translateY(-10px);
    }
    to {
        opacity: 1;
        transform: translateY(0);
    }
}

/* Loading */
.loading-spinner {
    display: flex;
    align-items: center;
    justify-content: center;
    padding: 3rem;
    color: #666;
    font-size: 1rem;
}

/* Responsive */
@media (max-width: 768px) {
    .settings-container {
        flex-direction: column;
        padding: 1rem;
    }

    .settings-sidebar {
        width: 100%;
    }

    .settings-nav {
        display: flex;
        overflow-x: auto;
        gap: 0.5rem;
    }

    .settings-nav li {
        white-space: nowrap;
    }
}

