{"file_text": "@page "/settings"
@using sv_ab5c6ecb0ec849ed99b4ac391fc83b0b.Services
@inject ISettingsService SettingsService
@rendermode InteractiveServer

<PageTitle>Settings</PageTitle>

<div class="settings-container">
    <nav class="settings-sidebar">
        <h2 class="settings-title">Settings</h2>
        <ul class="settings-nav">
            @foreach (var section in _sections)
            {
                <li class="@(ActiveSection == section.Key ? "active" : "")" @onclick="() => ActiveSection = section.Key">
                    <span class="nav-icon">@section.Value.Icon</span>
                    <span>@section.Value.Label</span>
                </li>
            }
        </ul>
    </nav>

    <main class="settings-content">
        @if (_loading)
        {
            <div class="loading-spinner">Loading...</div>
        }
        else
        {
            @if (!string.IsNullOrEmpty(_toastMessage))
            {
                <div class="toast @_toastType">@_toastMessage</div>
            }

            @switch (ActiveSection)
            {
                case "profile":
                    @RenderProfileSection()
                    break;
                case "notifications":
                    @RenderNotificationsSection()
                    break;
                case "security":
                    @RenderSecuritySection()
                    break;
                case "appearance":
                    @RenderAppearanceSection()
                    break;
            }
        }
    </main>
</div>

@* --- Profile Section --- *@
@{
    RenderFragment RenderProfileSection() => __builder2 =>
    {
        <section class="settings-section">
            <h3>Profile</h3>
            <div class="avatar-preview">
                <img src="@_profileDisplayName" alt="Avatar" onerror="this.style.display='none'" />
                @* Show avatar URL below *@
                <p class="avatar-url">@_profileAvatarUrl</p>
            </div>
            <div class="form-group">
                <label for="displayName">Display Name</label>
                <input id="displayName" type="text" @bind="_profileDisplayName" @bind:event="oninput" />
            </div>
            <div class="form-group">
                <label for="email">Email</label>
                <input id="email" type="email" @bind="_profileEmail" @bind:event="oninput" />
            </div>
            <div class="form-group">
                <label for="bio">Bio</label>
                <textarea id="bio" rows="4" @bind="_profileBio" @bind:event="oninput"></textarea>
            </div>
            <div class="form-group">
                <label for="avatarUrl">Avatar URL</label>
                <input id="avatarUrl" type="url" @bind="_profileAvatarUrl" @bind:event="oninput" />
            </div>
            <div class="button-group">
                <button class="btn btn-primary" @onclick="SaveProfile">Save Changes</button>
                <button class="btn btn-secondary" @onclick="DiscardProfileChanges">Discard Changes</button>
            </div>
        </section>
    };
}

@* --- Notifications Section --- *@
@{
    RenderFragment RenderNotificationsSection() => __builder2 =>
    {
        <section class="settings-section">
            <h3>Notifications</h3>
            <div class="toggle-group">
                <label class="toggle-item">
                    <span>Email Notifications</span>
                    <input type="checkbox" @bind="_emailNotifications" />
                    <span class="toggle-switch"></span>
                </label>
                <label class="toggle-item">
                    <span>Push Notifications</span>
                    <input type="checkbox" @bind="_pushNotifications" />
                    <span class="toggle-switch"></span>
                </label>
                <label class="toggle-item">
                    <span>Weekly Digest</span>
                    <input type="checkbox" @bind="_weeklyDigest" />
                    <span class="toggle-switch"></span>
                </label>
            </div>

            <h4>Muted Channels</h4>
            <div class="channel-list">
                @foreach (var channel in _allChannels)
                {
                    var isMuted = _mutedChannels.Contains(channel);
                    <label class="channel-item">
                        <input type="checkbox" checked="@isMuted" @onchange="e => ToggleMuteChannel(channel, (bool)e.Value!)" />
                        <span>@channel</span>
                    </label>
                }
            </div>

            <div class="button-group">
                <button class="btn btn-primary" @onclick="SaveNotifications">Save Preferences</button>
            </div>
        </section>
    };
}

@* --- Security Section --- *@
@{
    RenderFragment RenderSecuritySection() => __builder2 =>
    {
        <section class="settings-section">
            <h3>Security</h3>

            <div class="expandable-panel">
                <button class="panel-header" @onclick="() => _passwordPanelExpanded = !_passwordPanelExpanded">
                    <span>Change Password</span>
                    <span class="expand-icon">@(_passwordPanelExpanded ? "▾" : "▸")</span>
                </button>
                @if (_passwordPanelExpanded)
                {
                    <div class="panel-body">
                        <div class="form-group">
                            <label for="currentPassword">Current Password</label>
                            <input id="currentPassword" type="password" @bind="_currentPassword" />
                        </div>
                        <div class="form-group">
                            <label for="newPassword">New Password</label>
                            <input id="newPassword" type="password" @bind="_newPassword" />
                        </div>
                        <div class="form-group">
                            <label for="confirmPassword">Confirm Password</label>
                            <input id="confirmPassword" type="password" @bind="_confirmPassword" />
                        </div>
                        <button class="btn btn-primary" @onclick="UpdatePassword">Update Password</button>
                    </div>
                }
            </div>

            <div class="toggle-group" style="margin-top: 1.5rem;">
                <label class="toggle-item">
                    <span>Two-Factor Authentication</span>
                    <input type="checkbox" @bind="_twoFactorEnabled" />
                    <span class="toggle-switch"></span>
                    <span class="status-indicator @(_twoFactorEnabled ? "enabled" : "disabled")">
                        @(_twoFactorEnabled ? "Enabled" : "Disabled")
                    </span>
                </label>
            </div>

            @if (_securitySettings?.LastPasswordChange != null)
            {
                <p class="info-text">Last password change: @_securitySettings.LastPasswordChange.Value.ToString("MMMM dd, yyyy")</p>
            }

            <h4>Active Sessions</h4>
            <table class="sessions-table">
                <thead>
                    <tr>
                        <th>Device</th>
                        <th>Location</th>
                        <th>Last Active</th>
                        <th></th>
                    </tr>
                </thead>
                <tbody>
                    @if (_securitySettings?.Sessions != null)
                    {
                        @foreach (var session in _securitySettings.Sessions)
                        {
                            <tr>
                                <td>@session.Device</td>
                                <td>@session.Location</td>
                                <td>@FormatLastActive(session.LastActive)</td>
                                <td>
                                    @if (session.Id != _currentSessionId)
                                    {
                                        <button class="btn btn-danger btn-sm" @onclick="() => ConfirmRevokeSession(session)">Revoke</button>
                                    }
                                    else
                                    {
                                        <span class="current-badge">Current</span>
                                    }
                                </td>
                            </tr>
                        }
                    }
                </tbody>
            </table>

            @if (_sessionToRevoke != null)
            {
                <div class="modal-overlay" @onclick="CancelRevoke">
                    <div class="modal" @onclick:stopPropagation="true">
                        <h4>Confirm Session Revocation</h4>
                        <p>Are you sure you want to revoke the session on <strong>@_sessionToRevoke.Device</strong> from <strong>@_sessionToRevoke.Location</strong>?</p>
                        <div class="button-group">
                            <button class="btn btn-danger" @onclick="RevokeSession">Revoke Session</button>
                            <button class="btn btn-secondary" @onclick="CancelRevoke">Cancel</button>
                        </div>
                    </div>
                </div>
            }
        </section>
    };
}

@* --- Appearance Section --- *@
@{
    RenderFragment RenderAppearanceSection() => __builder2 =>
    {
        <section class="settings-section">
            <h3>Appearance</h3>

            <div class="form-group">
                <label>Theme</label>
                <div class="radio-group">
                    @foreach (var theme in new[] { "Light", "Dark", "System" })
                    {
                        <label class="radio-item">
                            <input type="radio" name="theme" value="@theme" checked="@(_appearanceTheme == theme)" @onchange="() => _appearanceTheme = theme" />
                            <span>@theme</span>
                        </label>
                    }
                </div>
            </div>

            <div class="form-group">
                <label>Font Size</label>
                <div class="radio-group">
                    @foreach (var size in new[] { "Small", "Medium", "Large" })
                    {
                        <label class="radio-item">
                            <input type="radio" name="fontSize" value="@size" checked="@(_appearanceFontSize == size)" @onchange="() => _appearanceFontSize = size" />
                            <span>@size</span>
                        </label>
                    }
                </div>
            </div>

            <div class="form-group">
                <label for="language">Language</label>
                <select id="language" @bind="_appearanceLanguage">
                    <option value="English">English</option>
                    <option value="Spanish">Spanish</option>
                    <option value="French">French</option>
                    <option value="German">German</option>
                    <option value="Japanese">Japanese</option>
                    <option value="Chinese">Chinese</option>
                </select>
